 * TEMP diagnostic: query devices table to debug 404 "Device Not Found" on /fleet/track-batch.
 * Usage: node apps/api/scripts/query-devices.cjs
 * Reads DATABASE_URL from apps/api/.env
 */
const { PrismaClient } = require('@prisma/client');
const fs = require('fs');
const path = require('path');

// Load .env manually (avoid dotenv import issues)
const envPath = path.join(__dirname, '..', '.env');
const envContent = fs.readFileSync(envPath, 'utf8');
for (const line of envContent.split('\n')) {
  const m = line.match(/^DATABASE_URL\s*=\s*"?([^"\n]+)"?/);
  if (m) {
    process.env.DATABASE_URL = m[1];
    break;
  }
}

if (!process.env.DATABASE_URL) {
  console.error('ERROR: DATABASE_URL not found in .env');
  process.exit(1);
}

async function main() {
  const prisma = new PrismaClient();
  try {
    console.log('=== DEVICES TABLE (all rows) ===');
    const devices = await prisma.device.findMany({
      select: {
        id: true,
        deviceId: true,
        taxiNumber: true,
        status: true,
        lastSeen: true,
        driverId: true,
      },
      orderBy: { lastSeen: 'desc' },
    });
    console.log(`Total devices: ${devices.length}\n`);
    for (const d of devices) {
      console.log(`  deviceId: ${d.deviceId} | taxi: ${d.taxiNumber} | status: ${d.status} | lastSeen: ${d.lastSeen} | driverId: ${d.driverId}`);
    }

    console.log('\n=== LAST 20 DRIVER LOCATIONS (telemetry attempts) ===');
    const recentLocs = await prisma.driverLocation.findMany({
      orderBy: { timestamp: 'desc' },
      take: 20,
      select: { deviceId: true, driverId: true, latitude: true, longitude: true, timestamp: true },
    });
    console.log(`Recent locations: ${recentLocs.length}\n`);
    for (const l of recentLocs) {
      console.log(`  deviceId: ${l.deviceId} | driverId: ${l.driverId} | lat: ${l.latitude} | lng: ${l.longitude} | ts: ${l.timestamp}`);
    }
  } catch (err) {
    console.error('Query error:', err.message);
  } finally {
    await prisma.$disconnect();
  }
}

main();
